import org.apache.commons.math3.distribution.ZipfDistribution;

public class PNL_IA {
  public static void main(String[] args) {
      // En Java, la Distribución Zipf de Commons Math asume que el 
      // conjunto de datos es finito (N elementos)
      int elementos = 10000;
      double a = 2.0;

      ZipfDistribution dist = new ZipfDistribution(elementos, a);
      System.out.println(dist.sample());
  }
}
